'use strict';
function plannerTypeFields(){if(!plannerOptions)return;const type=plannerOptions.elements.type.value;$$('[data-planner-fields]').forEach(node=>node.hidden=node.dataset.plannerFields!==type)}
function renderPlannerEntries(){
 const root=$('#planner-entries');if(!root)return;root.replaceChildren();
 if(!plannerEntries.length){const p=document.createElement('p');p.className='empty';p.textContent='Dodajte prvi vnos. Vaš načrt se shranjuje na tej napravi.';root.append(p)}
 for(const [index,entry] of plannerEntries.entries()){
  entry.entry_id ||= crypto.randomUUID();const row=document.createElement('article');row.className='planner-entry-row';
  const label=document.createElement('div');const title=document.createElement('strong');title.textContent=entry.title||entry.code||'Vnos';
  const meta=document.createElement('p');meta.textContent=[entry.date,[entry.time,entry.end_time].filter(Boolean).join('–'),entry.person,entry.room,entry.break?`Odmor: ${entry.break} min`:''].filter(Boolean).join(' · ');label.append(title,meta);
  const complete=document.createElement('input');complete.type='checkbox';complete.checked=entry.done==='1';complete.setAttribute('aria-label','Opravljeno: '+title.textContent);complete.addEventListener('change',()=>{entry.done=complete.checked?'1':'';savePlannerEntries();renderPlannerEntries()});
  const actions=document.createElement('div');actions.className='actions';const edit=document.createElement('button');edit.type='button';edit.textContent='Uredi';edit.addEventListener('click',()=>{const form=$('#planner-entry');for(const control of form.elements){if(!control.name)continue;if(control.type==='checkbox')control.checked=entry[control.name]==='1';else control.value=entry[control.name]||''}$('#save-planner-entry').textContent='Shrani spremembe';$('#cancel-planner-entry').hidden=false;form.elements.title.focus()});
  const remove=document.createElement('button');remove.type='button';remove.textContent='Odstrani';remove.addEventListener('click',()=>{plannerEntries.splice(index,1);savePlannerEntries();renderPlannerEntries()});actions.append(edit,remove);row.append(complete,label,actions);root.append(row)
 }
}
function resetPlannerEntry(){const form=$('#planner-entry');form.reset();form.elements.entry_id.value='';form.elements.date.value=plannerOptions.elements.date.value;$('#save-planner-entry').textContent='Dodaj vnos';$('#cancel-planner-entry').hidden=true}
if(plannerOptions){
 const saved=store.get('k365.options.'+location.pathname,null);if(saved)for(const [key,value]of Object.entries(saved)){const input=plannerOptions.elements[key];if(input&&key!=='photo_token')input.value=value}
 plannerTypeFields();refreshDesignPreviews();renderPlannerEntries();
 plannerOptions.addEventListener('change',event=>{const form=plannerOptions.elements;if(event.target.name==='year'||event.target.name==='month'){const year=Number(form.year.value),month=Number(form.month.value),day=Math.min(Number(form.date.value.slice(-2))||1,new Date(Date.UTC(year,month,0)).getUTCDate());form.date.value=`${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;refreshDesignPreviews()}plannerTypeFields()});
 $('#save-planner').addEventListener('click',()=>{const options=formObject(plannerOptions);delete options.photo_token;const ok=store.set('k365.options.'+location.pathname,options);say($('#planner-message'),ok?'Nastavitve so shranjene na tej napravi.':'Shramba ni na voljo. Shranite varnostno kopijo.',!ok)});
 $('#planner-entry').addEventListener('submit',event=>{event.preventDefault();const entry=formObject(event.currentTarget);const index=plannerEntries.findIndex(e=>e.entry_id===entry.entry_id);if(index<0&&plannerEntries.length>=100){say($('#planner-entry-status'),'Največ 100 vnosov v enem načrtu.',true);return}entry.entry_id ||= crypto.randomUUID();entry.done=entry.done||'';if(index>=0)plannerEntries[index]=entry;else {const additions=[entry];if(plannerOptions.elements.type.value==='school'&&$('#repeat-school').checked){const until=$('#repeat-school-until').value;if(!until||until<entry.date){say($('#planner-entry-status'),'Končni datum mora biti po začetnem.',true);return}let day=new Date(entry.date+'T12:00:00Z');for(day.setUTCDate(day.getUTCDate()+7);day.toISOString().slice(0,10)<=until;day.setUTCDate(day.getUTCDate()+7)){if(additions.length+plannerEntries.length>=100){say($('#planner-entry-status'),'Obdobje vsebuje več kot 100 vnosov. Izberite krajše obdobje.',true);return}additions.push({...entry,date:day.toISOString().slice(0,10),entry_id:crypto.randomUUID()})}}plannerEntries.push(...additions)}savePlannerEntries();renderPlannerEntries();resetPlannerEntry();say($('#planner-entry-status'),'Vnos je shranjen.')});
 $('#cancel-planner-entry').addEventListener('click',resetPlannerEntry);
 $('#planner-backup').addEventListener('click',()=>{const options=formObject(plannerOptions);delete options.photo_token;downloadBlob(new Blob([JSON.stringify({version:1,options,entries:plannerEntries},null,2)],{type:'application/json'}),'koledar365-planer.json')});
 $('#planner-restore').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file||file.size>1000000)throw Error('Izberite kopijo do 1 MB.');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.entries)||data.entries.length>100||data.entries.some(e=>typeof e.title!=='string'||e.title.length>200||!/^\d{4}-\d{2}-\d{2}$/.test(e.date)))throw Error('Varnostna kopija ni veljavna.');plannerEntries=data.entries;for(const [key,value] of Object.entries(data.options||{})){if(key!=='photo_token'&&plannerOptions.elements[key])plannerOptions.elements[key].value=value}savePlannerEntries();renderPlannerEntries();plannerTypeFields();refreshDesignPreviews();say($('#planner-entry-status'),'Kopija je obnovljena. Fotografijo po potrebi naložite znova.')}catch(error){say($('#planner-entry-status'),error.message,true)}});
 $('#planner-ics').addEventListener('click',async()=>{try{const response=await fetch('/planer/ics/',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf()},body:JSON.stringify({options:{...formObject(plannerOptions),entries:plannerEntries}})});if(!response.ok){const data=await response.json();throw Error(data.error||'Izvoz ni uspel.')}downloadBlob(await response.blob(),'koledar365-planer-2027-2030.ics');say($('#planner-entry-status'),'Koledar ICS je pripravljen.')}catch(error){say($('#planner-entry-status'),error.message,true)}});
 $('#calendar-photo').addEventListener('change',async event=>{const input=event.target,file=input.files[0];if(!file)return;const status=$('#photo-status');if(file.size>20*1024*1024){say(status,'Največja velikost fotografije je 20 MB.',true);return}input.disabled=true;say(status,'Pripravljamo fotografijo …');try{const data=new FormData();data.append('photo',file);const response=await fetch('/fotografija/',{method:'POST',headers:{'X-CSRF-Token':csrf()},body:data});const body=await response.json();if(!response.ok)throw Error(body.error||'Fotografije ni mogoče naložiti.');plannerOptions.elements.photo_token.value=body.token;$('#remove-photo').hidden=false;say(status,`Fotografija je pripravljena (${body.width} × ${body.height}). Odprite »Moj predogled« pri izbrani predlogi.`)}catch(error){say(status,error.message,true)}finally{input.disabled=false;input.value=''}});
 $('#remove-photo').addEventListener('click',()=>{plannerOptions.elements.photo_token.value='';$('#remove-photo').hidden=true;say($('#photo-status'),'Fotografija je odstranjena iz načrta.')});
}
$$('[data-personal-preview]').forEach(button=>button.addEventListener('click',async()=>{const section=button.closest('[data-export-options]'),card=button.closest('.design-card'),status=$('.export-status',card),image=$('img',card);const options={...JSON.parse(section.dataset.exportOptions),...(plannerOptions?formObject(plannerOptions):{}),design:button.dataset.personalPreview,paper:$('.export-paper',section).value,orientation:$('.export-orientation',section).value,entries:plannerOptions?plannerEntries:[]};button.disabled=true;say(status,'Pripravljamo vaš predogled …');try{const response=await fetch('/zasebni-predogled/',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf()},body:JSON.stringify({options})});if(!response.ok){const body=await response.json();throw Error(body.error||'Predogled ni uspel.')}if(image.dataset.objectUrl)URL.revokeObjectURL(image.dataset.objectUrl);const url=URL.createObjectURL(await response.blob());image.dataset.objectUrl=url;image.src=url;image.alt='Vaš osebni predogled: '+$('h3',card).textContent;say(status,`Vaš predogled · stran 1 od ${response.headers.get('X-Page-Count')}. Celotno datoteko prenesite s spodnjim gumbom.`)}catch(error){say(status,error.message,true)}finally{button.disabled=false}}));
let countdownTimer;
document.addEventListener('k365:countdown',event=>{clearInterval(countdownTimer);const target=new Date(event.detail.target).getTime(),offset=new Date(event.detail.server_now).getTime()-Date.now(),output=$('#live-countdown');const update=()=>{const remaining=target-(Date.now()+offset),seconds=Math.floor(Math.abs(remaining)/1000);output.textContent=`${remaining<0?'Od dogodka je minilo':'Do dogodka'}: ${Math.floor(seconds/86400)} d · ${String(Math.floor(seconds/3600)%24).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`};update();countdownTimer=setInterval(update,1000);$('#share-countdown').hidden=false});
const shareCountdown=$('#share-countdown');if(shareCountdown){const form=shareCountdown.closest('form'),params=new URLSearchParams(location.search);for(const key of ['date','time','zone'])if(params.has(key))form.elements[key].value=params.get(key);shareCountdown.addEventListener('click',async()=>{const url=new URL(location.href);url.search=new URLSearchParams({date:form.elements.date.value,time:form.elements.time.value,zone:form.elements.zone.value});try{await navigator.clipboard.writeText(url.href);say($('.result',form),'Povezava je kopirana.')}catch{say($('.result',form),url.href)}});if(params.has('date')&&form.checkValidity())form.requestSubmit()}
